/**
 * sakura-abm TS port test suite (bun:test).
 *
 * The headline claim: this TypeScript engine produces the SAME paired-seed
 * numbers as the Python engine for the same seeds. Parity fixtures in
 * tests/fixtures/ were generated by the Python engine (see
 * `bun run parity:regen`). Regenerate them whenever the Python engine changes.
 */

import { describe, expect, test } from "bun:test";
import { MT19937 } from "./engine/mt19937.ts";
import { buildBarabasiAlbert, runScenario } from "./engine/engine.ts";
import { compareScenarios } from "./engine/compare.ts";
import { validateInput } from "./engine/validate.ts";
import { configHash, validateOutput } from "./engine/output.ts";
import { runSimulation } from "./run_simulation.ts";

const ROOT = import.meta.dir + "/..";
const mtFixture = await Bun.file(`${ROOT}/tests/fixtures/mt_reference.json`).json();
const pyOutput = await Bun.file(`${ROOT}/tests/fixtures/python_output.json`).json();
const shippedConfig = await Bun.file(`${ROOT}/configs/example_experiment.json`).json();

describe("MT19937 CPython parity", () => {
  test("random() matches python.random.Random(42) bit-for-bit", () => {
    const rng = new MT19937(42);
    const values = Array.from({ length: 8 }, () => rng.random());
    expect(values).toEqual(mtFixture.random8);
  });

  test("randrange matches python _randbelow rejection sampling", () => {
    const rng = new MT19937(42);
    expect(Array.from({ length: 6 }, () => rng.randrange(30))).toEqual(mtFixture.randrange6_n30);
    const rng2 = new MT19937(42);
    expect(Array.from({ length: 4 }, () => rng2.randrange(13))).toEqual(mtFixture.randrange_n13);
  });

  test("stream is aligned across fresh instances with the same seed", () => {
    const a = new MT19937(42);
    const b = new MT19937(42);
    for (let i = 0; i < 1000; i++) expect(a.random()).toBe(b.random());
  });
});

describe("Barabasi-Albert graph parity", () => {
  test("BA(40, m=3, seed=42) adjacency matches python exactly", () => {
    const rng = new MT19937(42);
    const adj = buildBarabasiAlbert(40, 3, rng);
    expect(adj).toEqual(mtFixture.ba40m3_adj);
    const edges = adj.reduce((s, nb) => s + nb.length, 0) / 2;
    expect(edges).toBe(111);
  });
});

describe("engine parity vs python engine (fixtures)", () => {
  const pyParsed = validateInput(JSON.parse(JSON.stringify(shippedConfig)));
  const pyScenarioById = new Map(pyOutput.scenarios.map((s: any) => [s.id, s]));

  for (const scenario of pyParsed.scenarios) {
    test(`scenario ${scenario.id}: totals + per-round match python for all seeds`, () => {
      const seeds = pyOutput.scenarios.find((s: any) => s.id === scenario.id).variability.seeds;
      for (const seed of seeds) {
        const got = runScenario(pyParsed, scenario, seed);
        const want = pyScenarioById.get(scenario.id);
        // headline seed is the first repetition in the python output block
        if (seed === want.seed) {
          const { data_label: _dl, ...wantTotals } = want.totals; // data_label is added by buildOutput, not the engine
          expect(got.totals).toEqual(wantTotals);
          expect(got.per_round).toEqual(want.per_round);
          expect(got.per_segment).toEqual(want.per_segment);
          expect(got.per_language).toEqual(want.per_language);
          expect(got.graph).toEqual(want.graph);
        } else {
          // variability members: compare against the aggregate stats
          const reps = (want as any).variability;
          expect(got.totals.engagement_rate).toBeGreaterThanOrEqual(reps.engagement_rate.min);
          expect(got.totals.engagement_rate).toBeLessThanOrEqual(reps.engagement_rate.max);
        }
      }
    });
  }

  test("paired comparison block matches python (means, stds, segment deltas, drivers)", () => {
    const runs: Record<string, any[]> = {};
    for (const scenario of pyParsed.scenarios) {
      const seeds = pyScenarioById.get(scenario.id).variability.seeds;
      runs[scenario.id] = seeds.map((seed: number) => ({ ...runScenario(pyParsed, scenario, seed), seed }));
    }
    const comparisons = compareScenarios(pyParsed, runs, pyOutput.comparisons[0].baseline_id);
    const want = pyOutput.comparisons[0];
    expect(comparisons.length).toBe(1);
    const got = comparisons[0];
    expect(got.baseline_id).toBe(want.baseline_id);
    expect(got.scenario_id).toBe(want.scenario_id);
    for (const key of Object.keys(want.metrics)) {
      expect(got.metrics[key].baseline_mean).toBeCloseTo(want.metrics[key].baseline_mean, 9);
      expect(got.metrics[key].comparison_mean).toBeCloseTo(want.metrics[key].comparison_mean, 9);
      expect(got.metrics[key].delta_mean).toBeCloseTo(want.metrics[key].delta_mean, 9);
      expect(got.metrics[key].delta_std).toBeCloseTo(want.metrics[key].delta_std, 9);
      expect(got.metrics[key].delta_min).toBeCloseTo(want.metrics[key].delta_min, 9);
      expect(got.metrics[key].delta_max).toBeCloseTo(want.metrics[key].delta_max, 9);
      expect(got.metrics[key].relative_lift_mean).toBeCloseTo(want.metrics[key].relative_lift_mean, 9);
    }
    expect(got.per_segment_engagement_delta).toEqual(want.per_segment_engagement_delta);
    expect(got.drivers).toEqual(want.drivers);
  });
});

describe("run_simulation end-to-end (bun engine)", () => {
  test("full envelope reproduces the python run: status, totals, comparisons, assumptions, hash", async () => {
    const got = await runSimulation(JSON.parse(JSON.stringify(shippedConfig)), {
      configDir: `${ROOT}/configs`,
    });
    expect(got.simulation_status).toBe(pyOutput.simulation_status);
    expect(got.schema_version).toBe("1.0");
    expect(got.ip_id).toBe(pyOutput.ip_id);
    expect(got.experiment_id).toBe(pyOutput.experiment_id);
    expect(got.engine).toBe("sakura-abm");

    for (let i = 0; i < pyOutput.scenarios.length; i++) {
      expect(got.scenarios[i].id).toBe(pyOutput.scenarios[i].id);
      expect(got.scenarios[i].totals).toEqual(pyOutput.scenarios[i].totals);
      expect(got.scenarios[i].per_round).toEqual(pyOutput.scenarios[i].per_round);
      expect(got.scenarios[i].per_segment).toEqual(pyOutput.scenarios[i].per_segment);
      expect(got.scenarios[i].per_language).toEqual(pyOutput.scenarios[i].per_language);
      expect(got.scenarios[i].variability).toEqual(pyOutput.scenarios[i].variability);
    }
    expect(got.comparisons[0].metrics).toEqual(pyOutput.comparisons[0].metrics);
    expect(got.comparisons[0].per_segment_engagement_delta).toEqual(pyOutput.comparisons[0].per_segment_engagement_delta);
    expect(got.assumptions).toEqual(pyOutput.assumptions);
    expect(got.source_references).toEqual(pyOutput.source_references);
    expect(got.limitations).toEqual(pyOutput.limitations);
    expect(got.run_metadata.config_hash).toBe(pyOutput.run_metadata.config_hash);
    expect(got.run_metadata.seeds).toEqual(pyOutput.run_metadata.seeds);
  });

  test("reproducibility: two runs differ only in timestamps/durations", async () => {
    const a = await runSimulation(JSON.parse(JSON.stringify(shippedConfig)), { configDir: `${ROOT}/configs` });
    const b = await runSimulation(JSON.parse(JSON.stringify(shippedConfig)), { configDir: `${ROOT}/configs` });
    delete a.run_metadata.generated_at;
    delete b.run_metadata.generated_at;
    delete a.run_metadata.total_duration_ms;
    delete b.run_metadata.total_duration_ms;
    for (const s of a.scenarios) delete s.duration_ms;
    for (const s of b.scenarios) delete s.duration_ms;
    expect(a).toEqual(b);
  });

  test("paired monotonicity: dub is a language superset, so engaged count never decreases (per seed)", async () => {
    const parsed = validateInput(JSON.parse(JSON.stringify(shippedConfig)));
    const seeds = [42, 43, 44, 45, 46];
    for (const seed of seeds) {
      const base = runScenario(parsed, parsed.scenarios[0], seed);
      const dub = runScenario(parsed, parsed.scenarios[1], seed);
      expect(dub.totals.engaged).toBeGreaterThanOrEqual(base.totals.engaged);
      expect(dub.totals.reach).toBeGreaterThanOrEqual(base.totals.reach);
    }
  });

  test("output contract self-validation passes", async () => {
    const got = await runSimulation(JSON.parse(JSON.stringify(shippedConfig)), { configDir: `${ROOT}/configs` });
    expect(validateOutput(got)).toEqual([]);
  });

  test("invalid config → structured failure envelope, never a throw", async () => {
    const bad = { schema_version: "1.0", ip_id: "x" }; // missing title, segments, scenarios...
    const got = await runSimulation(bad);
    expect(got.simulation_status).toBe("failed");
    expect(got.errors[0].code).toBe("MISSING_FIELD");
    expect(got.errors[0].context).toBe("root");
    expect(got.limitations.length).toBeGreaterThan(0);
  });

  test("unsupported engine → INVALID_ENGINE envelope", async () => {
    const bad = { ...JSON.parse(JSON.stringify(shippedConfig)), engine: "oasis" };
    const got = await runSimulation(bad);
    expect(got.simulation_status).toBe("failed");
    expect(got.errors[0].code).toBe("INVALID_ENGINE");
  });

  test("bad evidence label → BAD_EVIDENCE_LABEL envelope", async () => {
    const bad = JSON.parse(JSON.stringify(shippedConfig));
    bad.evidence = [{ id: "e1", title: "t", url: "https://x", publisher: "p", date: "d", finding: "f", type: "news", region: "IN", label: "simulated", quality: "high" }];
    const got = await runSimulation(bad);
    expect(got.simulation_status).toBe("failed");
    expect(got.errors[0].code).toBe("BAD_EVIDENCE_LABEL");
  });
});

describe("config hash parity", () => {
  test("canonical hash matches the python-computed config_hash", () => {
    const parsed = validateInput(JSON.parse(JSON.stringify(shippedConfig)));
    expect(configHash(parsed)).toBe(pyOutput.run_metadata.config_hash);
    expect(configHash(parsed)).toBe("998c04165d5a0bc3");
  });
});
